mapper.update:
UPDATE sign_bitmap
SET bits = bits | #{mask}, update_time = NOW()
WHERE user_id = #{userId}
  AND `year_month` = #{yearMonth}
  AND (bits & #{mask}) = 0

mapper.select:
SELECT user_id, `year_month`, bits, update_time
FROM sign_bitmap
WHERE user_id = #{userId} AND `year_month` = #{yearMonth}

SELECT COALESCE(SUM(BIT_COUNT(bits)), 0)
FROM sign_bitmap
WHERE user_id = #{userId}
